Tr.Begin();
int a = 5, b = 3;
Tr.S("صندوق لكل متغير: a فيه 5، وb فيه 3.", "a", a, "b", b);
int c = a + b;
Tr.S("نحسب a + b = 5 + 3 ونضع 8 في صندوق جديد c.", "c", c);
a = a * 2;
Tr.S("a يأخذ 5 × 2 = 10، والقيمة القديمة 5 تُمحى. c لا يتغير: حُسب مرة واحدة.", "a", a);
Console.WriteLine(a + " " + b + " " + c);
Tr.S("الطباعة: القيم الحالية بينها مسافات.");
Tr.End();

Tr.Begin();
int x = 4, y = 9;
Tr.S("x = 4 وy = 9.", "x", x, "y", y);
int t = x;
Tr.S("نحفظ قيمة x في صندوق مؤقت t قبل أن نكتب فوقها.", "t", t);
x = y;
Tr.S("x يأخذ 9، والقيمة 4 ما زالت محفوظة في t.", "x", x);
y = t;
Tr.S("y يأخذ 4 من t: تم التبديل.", "y", y);
Console.WriteLine(x + " " + y);
Tr.S("الطباعة: 9 4.");
Tr.End();
